import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { BrowserRouter as Router, Routes, Route, Link, useNavigate } from 'react-router-dom';

// --- NAVBAR: White Glassmorphism ---
const Navbar = ({ cartCount }) => (
  <nav className="bg-white/80 backdrop-blur-md sticky top-0 z-50 w-full border-b border-gray-200/50 shadow-sm">
    <div className="max-w-7xl mx-auto px-6 h-20 flex justify-between items-center">

      {/* LOGO */}
      <Link to="/" className="flex items-center space-x-3 group">
        <div className="bg-orange-600 p-2.5 rounded-full shadow-md">
          <svg width="20" height="20" viewBox="0 0 512 512" fill="white" xmlns="http://www.w3.org/2000/svg">
            <path d="M416 0C380.7 0 352 28.7 352 64V288c0 17.7 14.3 32 32 32h32V480c0 17.7 14.3 32 32 32s32-14.3 32-32V32C480 14.3 465.7 0 448 0H416zM80 0C44.7 0 16 28.7 16 64V224c0 35.3 28.7 64 64 64h16V480c0 17.7 14.3 32 32 32s32-14.3 32-32V288h16c35.3 0 64-28.7 64-64V64c0-35.3-28.7-64-64-64H80zM128 0V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H80V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H16V192c0 53 43 96 96 96v192c0 17.7 14.3 32 32 32s32-14.3 32-32V288c53 0 96-43 96-96V0H224V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H160V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H128z" />
          </svg>
        </div>
        <span className="font-black text-xl tracking-tighter text-gray-900 uppercase italic">Fast<span className="text-orange-600">Délice</span></span>
      </Link>

      <div className="hidden md:flex space-x-10 text-[11px] font-black uppercase tracking-widest text-gray-400">
        <Link to="/" className="hover:text-orange-600 transition">Accueil</Link>
        <Link to="/menu" className="hover:text-orange-600 transition">Menu</Link>
        <Link to="/about" className="hover:text-orange-600 transition">À Propos</Link>
      </div>

      <div className="flex items-center space-x-6">
        <Link to="/panier" className="relative flex items-center space-x-2 text-gray-800 hover:text-orange-600 transition">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z" />
          </svg>
